async def act(page):
    import re

    # Navigate to Manage Products using a relative path
    await page.goto('/index.php/admin/catalog_product/')
    await page.wait_for_load_state('networkidle')

    skus = []

    tables = page.get_by_role('table')
    table_count = await tables.count()

    for ti in range(table_count):
        tbl = tables.nth(ti)
        rows = tbl.get_by_role('row')
        row_count = await rows.count()
        if row_count < 2:
            continue

        # Read header row and normalize NBSPs
        header_row = rows.nth(0)
        try:
            header_text = (await header_row.inner_text()) or ''
        except Exception:
            continue
        header_text = header_text.replace('\u00A0', ' ')
        lheader = header_text.lower()

        # Look for both SKU and Qty/Quantity in header text
        if 'sku' not in lheader or ('qty' not in lheader and 'quantity' not in lheader):
            continue

        # Determine header cell indices (try 'cell' then fallback to 'columnheader')
        header_cells = header_row.get_by_role('cell')
        hc = await header_cells.count()
        if hc == 0:
            header_cells = header_row.get_by_role('columnheader')
            hc = await header_cells.count()

        sku_idx = None
        qty_idx = None
        for j in range(hc):
            try:
                txt = (await header_cells.nth(j).inner_text()) or ''
            except Exception:
                txt = ''
            txt = txt.strip().replace('\u00A0', ' ')
            tl = txt.lower()
            if 'sku' in tl and sku_idx is None:
                sku_idx = j
            if ('qty' in tl or 'quantity' in tl) and qty_idx is None:
                qty_idx = j

        if sku_idx is None or qty_idx is None:
            continue

        # Iterate data rows and collect SKUs where qty is between 1 and 3 inclusive
        for ri in range(1, row_count):
            data_row = rows.nth(ri)
            data_cells = data_row.get_by_role('cell')
            dc = await data_cells.count()
            if dc <= max(sku_idx, qty_idx):
                continue

            try:
                sku_text = (await data_cells.nth(sku_idx).inner_text()) or ''
            except Exception:
                sku_text = ''
            try:
                qty_text = (await data_cells.nth(qty_idx).inner_text()) or ''
            except Exception:
                qty_text = ''

            sku_text = sku_text.strip()
            qty_norm = qty_text.replace('\u00A0', ' ').replace(',', '').strip()
            m = re.search(r'-?\d+', qty_norm)
            if not m:
                continue
            try:
                qty = int(m.group(0))
            except Exception:
                continue

            if 1 <= qty <= 3:
                skus.append(sku_text)

        # If we found SKUs assume this is the products grid and stop
        if skus:
            break

    # Print SKUs one-per-line so the runner can capture them; also return the list
    if skus:
        print('\n'.join(skus))
    else:
        print('')

    return skus

